976: impl Widget for &Chart<'_> {
977:     #[expect(clippy::too_many_lines)]
978:     fn render(self, area: Rect, buf: &mut Buffer) {
979:         buf.set_style(area, self.style);
980: 
981:         self.block.as_ref().render(area, buf);
982:         let chart_area = self.block.inner_if_some(area);
983:         let Some(layout) = self.layout(chart_area) else {
984:             return;
985:         };
986:         let graph_area = layout.graph_area;
987: 
988:         // Sample the style of the entire widget. This sample will be used to reset the style of
989:         // the cells that are part of the components put on top of the grah area (i.e legend and
990:         // axis names).
991:         let original_style = buf[(area.left(), area.top())].style();
992: 
993:         self.render_x_labels(buf, &layout, chart_area, graph_area);
994:         self.render_y_labels(buf, &layout, chart_area, graph_area);
995: 
996:         if let Some(y) = layout.axis_x {
997:             for x in graph_area.left()..graph_area.right() {
998:                 buf[(x, y)]
999:                     .set_symbol(symbols::line::HORIZONTAL)
1000:                     .set_style(self.x_axis.style);
1001:             }
1002:         }
1003: 
1004:         if let Some(x) = layout.axis_y {
1005:             for y in graph_area.top()..graph_area.bottom() {
1006:                 buf[(x, y)]
1007:                     .set_symbol(symbols::line::VERTICAL)
1008:                     .set_style(self.y_axis.style);
1009:             }
1010:         }
1011: 
1012:         if let Some(y) = layout.axis_x {
1013:             if let Some(x) = layout.axis_y {
1014:                 buf[(x, y)]
1015:                     .set_symbol(symbols::line::BOTTOM_LEFT)
1016:                     .set_style(self.x_axis.style);
1017:             }
1018:         }
1019: 
1020:         for dataset in &self.datasets {
1021:             Canvas::default()
1022:                 .background_color(self.style.bg.unwrap_or(Color::Reset))
1023:                 .x_bounds(self.x_axis.bounds)
1024:                 .y_bounds(self.y_axis.bounds)
1025:                 .marker(dataset.marker)
1026:                 .paint(|ctx| {
1027:                     ctx.draw(&Points {
1028:                         coords: dataset.data,
1029:                         color: dataset.style.fg.unwrap_or(Color::Reset),
1030:                     });
1031:                     match dataset.graph_type {
1032:                         GraphType::Line => {
1033:                             for data in dataset.data.windows(2) {
1034:                                 ctx.draw(&CanvasLine {
1035:                                     x1: data[0].0,
1036:                                     y1: data[0].1,
1037:                                     x2: data[1].0,
1038:                                     y2: data[1].1,
1039:                                     color: dataset.style.fg.unwrap_or(Color::Reset),
1040:                                 });
1041:                             }
1042:                         }
1043:                         GraphType::Bar => {
1044:                             for (x, y) in dataset.data {
1045:                                 ctx.draw(&CanvasLine {
1046:                                     x1: *x,
1047:                                     y1: 0.0,
1048:                                     x2: *x,
1049:                                     y2: *y,
1050:                                     color: dataset.style.fg.unwrap_or(Color::Reset),
1051:                                 });
1052:                             }
1053:                         }
1054:                         GraphType::Scatter => {}
1055:                     }
1056:                 })
1057:                 .render(graph_area, buf);
1058:         }
1059: 
1060:         if let Some(Position { x, y }) = layout.title_x {
1061:             let title = self.x_axis.title.as_ref().unwrap();
1062:             let width = graph_area
1063:                 .right()
1064:                 .saturating_sub(x)
1065:                 .min(title.width() as u16);
1066:             buf.set_style(
1067:                 Rect {
1068:                     x,
1069:                     y,
1070:                     width,
1071:                     height: 1,
1072:                 },
1073:                 original_style,
1074:             );
1075:             buf.set_line(x, y, title, width);
1076:         }
1077: 
1078:         if let Some(Position { x, y }) = layout.title_y {
1079:             let title = self.y_axis.title.as_ref().unwrap();
1080:             let width = graph_area
1081:                 .right()
1082:                 .saturating_sub(x)
1083:                 .min(title.width() as u16);
1084:             buf.set_style(
1085:                 Rect {
1086:                     x,
1087:                     y,
1088:                     width,
1089:                     height: 1,
1090:                 },
1091:                 original_style,
1092:             );
1093:             buf.set_line(x, y, title, width);
1094:         }
1095: 
1096:         if let Some(legend_area) = layout.legend_area {
1097:             buf.set_style(legend_area, original_style);
1098:             Block::bordered().render(legend_area, buf);
1099: 
1100:             for (i, (dataset_name, dataset_style)) in self
1101:                 .datasets
1102:                 .iter()
1103:                 .filter_map(|ds| Some((ds.name.as_ref()?, ds.style())))
1104:                 .enumerate()
1105:             {
1106:                 let name = dataset_name.clone().patch_style(dataset_style);
1107:                 name.render(
1108:                     Rect {
1109:                         x: legend_area.x + 1,
1110:                         y: legend_area.y + 1 + i as u16,
1111:                         width: legend_area.width - 2,
1112:                         height: 1,
1113:                     },
1114:                     buf,
1115:                 );
1116:             }
1117:         }
1118:     }
1119: }
